def transform(g):
    H,W=len(g),len(g[0])
    cnt={}
    for row in g:
        for v in row: cnt[v]=cnt.get(v,0)+1
    seed=min((c for c in cnt if c!=0), key=lambda c: cnt[c])
    seeds=[(i,j) for i in range(H) for j in range(W) if g[i][j]==seed]
    r0=min(p[0] for p in seeds); c0=min(p[1] for p in seeds)
    Srel=sorted((i-r0,j-c0) for i,j in seeds)
    h=max(a for a,b in Srel)+1; w=max(b for a,b in Srel)+1
    out=[row[:] for row in g]
    for i in range(H-h+1):
        for j in range(W-w+1):
            if all(g[i+a][j+b]==0 for a,b in Srel):
                for a,b in Srel: out[i+a][j+b]=seed
    return out
